(() => {
  const esc = value => String(value ?? '').replace(/[&<>'"]/g, char => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', "'": '&#039;', '"': '&quot;' }[char]));
  const num = value => Number(value || 0).toLocaleString('ru-RU');
  const date = value => value ? new Date(value).toLocaleString('ru-RU', { day: '2-digit', month: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit' }) : '—';
  const money = (amount, type) => `${num(amount)} ${type === 'gems' ? '💎' : '🪙'}`;
  const metric = (label, value, tone = '') => `<div class="admin-metric ${tone}"><small>${label}</small><b>${esc(value)}</b></div>`;
  const tabs = active => ['dashboard', 'players', 'economy', 'shop', 'payments', 'games', 'security', 'logs'].map(id => `<button class="admin-tab ${active === id ? 'active' : ''}" type="button" data-admin-tab="${id}">${({ dashboard: 'Dashboard', players: 'Players', economy: 'Economy', shop: 'Shop', payments: 'Payments', games: 'Games', security: 'Security / Rewards', logs: 'Logs' })[id]}</button>`).join('');
  const playerCard = player => {
    const ownedProfile = player.inventory?.profile?.ownedItems?.length || 0, ownedGames = Object.values(player.inventory?.games || {}).reduce((sum, scope) => sum + (scope.ownedItems?.length || 0), 0);
    const migrationLabel = player.migration?.completed ? `Completed · ${player.migration.version || 'v1'}` : 'Not required';
    return `<button type="button" class="admin-player-card" data-admin-player="${esc(player.id)}"><div class="admin-player-card-top"><span class="admin-avatar">${esc((player.username || 'T').slice(0, 1).toUpperCase())}</span><div><b>${esc(player.username)}</b><small>Telegram ID · ${esc(player.id)}</small></div><span class="admin-status">${esc(player.source || 'LIVE')}</span></div><div class="admin-player-grid"><span><small>LEVEL</small><b>${num(player.level)}</b></span><span><small>XP</small><b>${num(player.xp)}</b></span><span><small>RANK</small><b>${esc(player.rank)}</b></span><span><small>COINS</small><b>${money(player.coins, 'coins')}</b></span><span><small>GEMS</small><b>${money(player.gems, 'gems')}</b></span><span><small>ACHIEVEMENTS</small><b>${num(player.achievements)}</b></span><span><small>INVENTORY</small><b>${num(ownedProfile + ownedGames)}</b></span><span><small>ACCOUNT</small><b>Telegram</b></span><span><small>MIGRATION</small><b>${esc(migrationLabel)}</b></span></div><span class="admin-player-open">Открыть профиль ›</span></button>`;
  };
  const playerDetail = player => {
    if (!player) return '';
    const games = Object.entries(player.statistics?.launchesByGame || {}).map(([id, count]) => `${id}: ${count}`).join(' · ') || 'Нет игровых сессий';
    const items = [...(player.inventory?.profile?.ownedItems || []), ...Object.values(player.inventory?.games || {}).flatMap(scope => scope.ownedItems || [])];
    const migration = player.migration || {}, accountLabel = player.account?.source === 'telegram_registration' ? 'Telegram Registration' : (player.account?.source || 'Telegram');
    return `<section class="admin-player-detail"><div class="admin-block-title"><span><span class="eyebrow">PLAYER PROFILE</span><h3>${esc(player.username)}</h3></span><small>${esc(player.source || 'LIVE')} · ID ${esc(player.id)}</small></div><div class="admin-player-detail-grid"><span><small>ACCOUNT</small><b>${esc(accountLabel)}</b></span><span><small>MIGRATION</small><b>${migration.completed ? 'Completed' : 'Not required'}</b></span><span><small>MIGRATION DATE</small><b>${esc(migration.completedAt ? date(migration.completedAt) : '—')}</b></span><span><small>MIGRATION VERSION</small><b>${esc(migration.version || '—')}</b></span><span><small>REGISTRATION</small><b>${esc(player.createdAt ? new Date(player.createdAt).toLocaleString('ru-RU') : '—')}</b></span><span><small>LAST ACTIVE</small><b>${esc(player.lastActive || '—')}</b></span><span><small>SESSIONS</small><b>${num(player.statistics?.totalGames || player.statistics?.sessions)}</b></span><span><small>FAVORITE</small><b>${esc(player.statistics?.favoriteGame || '—')}</b></span><span><small>RECENT GAMES</small><b>${esc(games)}</b></span><span><small>PURCHASES / ITEMS</small><b>${num(items.length)}</b></span><span><small>TRANSACTIONS</small><b>${num((player.transactions || []).length)}</b></span><span><small>ACHIEVEMENTS</small><b>${num(player.achievements)}</b></span></div></section>`;
  };
  const actionForms = player => {
    const achievements = window.TelePlayPlayer?.Achievements?.CATALOG || [], profileItems = window.TelePlayShopConfig?.ITEMS || [], games = window.TelePlayCatalog?.games || [], gameItems = games.flatMap(game => (window.TelePlayGameShops?.[game.id]?.getItems?.('all') || []).map(item => ({ ...item, gameId: game.id, gameTitle: game.title })));
    return `<div class="admin-actions-block"><div class="admin-block-title"><span class="eyebrow">OWNER ACTIONS</span><small>Все операции проходят через ядро и журналируются</small></div><div class="admin-action-grid"><form data-admin-action="currency" class="admin-action-form"><h4>Валюта</h4><div class="admin-form-row"><select name="currencyType"><option value="coins">TeleCoins</option><option value="gems">TeleGems</option></select><input name="amount" type="number" step="1" placeholder="+500 или -100" required></div><input name="reason" placeholder="Причина" required><button type="submit">Применить</button></form><form data-admin-action="xp" class="admin-action-form"><h4>Прогресс</h4><input name="totalXP" type="number" min="0" step="1" placeholder="Общий XP" required><input name="reason" placeholder="Причина" required><button type="submit">Изменить XP</button></form><form data-admin-action="streak" class="admin-action-form"><h4>Streak</h4><input name="currentStreak" type="number" min="0" step="1" placeholder="Текущая серия" required><input name="bestStreak" type="number" min="0" step="1" placeholder="Лучшая серия"><input name="reason" placeholder="Причина" required><button type="submit">Изменить streak</button></form><form data-admin-action="achievement" class="admin-action-form"><h4>Achievement</h4><select name="achievementId">${achievements.map(item => `<option value="${esc(item.id)}">${esc(item.title)}</option>`).join('')}</select><input name="reason" placeholder="Причина" required><div class="admin-form-row"><button type="submit" name="mode" value="grant">Выдать</button><button type="submit" name="mode" value="revoke" class="danger">Отозвать</button></div></form><form data-admin-action="item" class="admin-action-form"><h4>Profile Item</h4><select name="itemId">${profileItems.map(item => `<option value="${esc(item.id)}">${esc(item.name)}</option>`).join('')}</select><input name="reason" placeholder="Причина" required><div class="admin-form-row"><button type="submit" name="mode" value="grant">Выдать</button><button type="submit" name="mode" value="revoke" class="danger">Отозвать</button></div></form><form data-admin-action="game-item" class="admin-action-form"><h4>Game Cosmetic</h4><select name="itemId">${gameItems.map(item => `<option value="${esc(item.id)}" data-game-id="${esc(item.gameId)}">${esc(item.gameTitle)} · ${esc(item.name)}</option>`).join('')}</select><input name="reason" placeholder="Причина" required><div class="admin-form-row"><button type="submit" name="mode" value="grant">Выдать</button><button type="submit" name="mode" value="revoke" class="danger">Отозвать</button></div></form></div></div>`;
  };
  const dashboard = (data, analytics = {}) => `<div class="admin-section-intro"><div><span class="eyebrow">OWNER DASHBOARD</span><h3>TelePlay control room</h3><p>${data.scope === 'local-device' ? 'Локальный режим сохранён как fallback. Подключите API, чтобы видеть всех игроков.' : 'Данные загружены из глобального источника игроков.'}</p></div><span class="admin-scope">${data.scope === 'local-device' ? 'LOCAL DATA' : 'GLOBAL DATA'}</span></div><div class="admin-metric-grid">${metric('PLAYERS TOTAL', data.playersTotal)}${metric('ACTIVE TODAY', data.activeToday, 'mint')}${metric('NEW PLAYERS', data.newPlayers)}${metric('GAMES TODAY', data.gamesPlayedToday, 'violet')}${metric('TOTAL SESSIONS', data.totalSessions)}${metric('AVG SESSION', `${data.averageSessionTime} sec`, 'cyan')}</div><section class="admin-funnel"><div class="admin-block-title"><span><span class="eyebrow">PRODUCT FUNNEL</span><h3>Первый игровой цикл</h3></span><small>${esc(analytics.scope || 'Нет событий')}</small></div><div class="admin-metric-grid">${metric('APP OPENED', analytics.appOpened || 0, 'cyan')}${metric('GAME SELECTED', `${analytics.gameSelected || 0} · ${analytics.selectionRate || 0}%`, 'violet')}${metric('GAME STARTED', `${analytics.gameStarted || 0} · ${analytics.firstGameRate || 0}%`, 'mint')}${metric('GAME FINISHED', `${analytics.gameFinished || 0} · ${analytics.completionRate || 0}%`)}${metric('PAYMENT STARTED', analytics.paymentStarted || 0)}${metric('PAYMENT COMPLETED', `${analytics.paymentCompleted || 0} · ${analytics.paymentRate || 0}%`, 'mint')}</div><p class="admin-funnel-note">Конверсия считается по уникальным игрокам в загруженной выборке. Для retention понадобятся накопленные cohorts после запуска.</p></section><div class="admin-callout">🔐 Сервер обязан проверять Telegram initData, роль OWNER и права операции. Клиентская панель не является источником истины.</div>`;
  const players = (rows, selected = {}) => {
    const status = selected.globalStatus || {}, isBackend = status.scope === 'backend', unavailable = isBackend && status.state === 'error';
    const scope = isBackend ? (unavailable ? 'GLOBAL UNAVAILABLE' : 'GLOBAL DATA') : 'LOCAL DATA';
    const empty = unavailable ? '<div class="admin-empty">Не удалось обновить список игроков.<button type="button" data-admin-retry-global>Повторить</button></div>' : '<div class="admin-empty">Игрок не найден.</div>';
    return `<div class="admin-section-intro"><div><span class="eyebrow">PLAYER MANAGEMENT</span><h3>Players</h3><p>Глобальный список загружается через Data Provider. При локальном режиме доступен текущий профиль.</p></div><span class="admin-scope">${scope}</span></div><form class="admin-search" data-admin-search><input name="query" value="${esc(selected.query || '')}" placeholder="Telegram ID или nickname"><select name="filter"><option value="">Все игроки</option><option value="new" ${selected.filter === 'new' ? 'selected' : ''}>Новые</option><option value="active" ${selected.filter === 'active' ? 'selected' : ''}>Активны сегодня</option></select><select name="sort"><option value="">По имени</option><option value="level" ${selected.sort === 'level' ? 'selected' : ''}>Высший уровень</option><option value="played" ${selected.sort === 'played' ? 'selected' : ''}>Больше игр</option></select><button type="submit">Найти</button></form><div class="admin-player-list">${rows.length ? rows.map(playerCard).join('') : empty}</div>${selected.player ? playerDetail(selected.player) : ''}${selected.player ? actionForms(selected.player) : ''}`;
  };
  const economy = data => `<div class="admin-section-intro"><div><span class="eyebrow">ECONOMY</span><h3>Economy Dashboard</h3><p>Все операции читаются из typed Transaction History.</p></div></div><div class="admin-metric-grid">${metric('COINS GENERATED', money(data.coins.generated, 'coins'), 'mint')}${metric('COINS SPENT', money(data.coins.spent, 'coins'))}${metric('COINS BALANCE', money(data.coins.balance, 'coins'), 'violet')}${metric('GEMS GENERATED', money(data.gems.generated, 'gems'), 'mint')}${metric('GEMS SPENT', money(data.gems.spent, 'gems'))}${metric('GEMS BALANCE', money(data.gems.balance, 'gems'), 'violet')}</div><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Игрок</th><th>Валюта</th><th>Тип</th><th>Источник</th><th>Количество</th><th>Дата</th></tr></thead><tbody>${data.transactions.slice(0, 40).map(item => `<tr><td>current</td><td>${item.currencyType === 'gems' ? '💎 Gems' : '🪙 Coins'}</td><td>${item.type === 'spend' ? 'SPEND' : 'EARN'}</td><td>${esc(item.source || 'system')}</td><td class="${item.type === 'spend' ? 'negative' : 'positive'}">${item.direction}${num(item.amount)}</td><td>${esc(item.date)}</td></tr>`).join('') || '<tr><td colspan="6">Нет операций</td></tr>'}</tbody></table></div>`;
  const shop = items => `<div class="admin-section-intro"><div><span class="eyebrow">SHOP CONTROL</span><h3>Catalog & prices</h3><p>Просмотр товаров и покупок. Изменение цен оставлено для серверной версии.</p></div></div><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Предмет</th><th>Раздел</th><th>Редкость</th><th>Цена</th><th>Покупки</th></tr></thead><tbody>${items.map(item => { const price = item.price && typeof item.price === 'object' ? item.price : { currency: 'coins', amount: item.price || 0 }; return `<tr><td><b>${esc(item.name)}</b><small>${esc(item.gameId || 'TelePlay')}</small></td><td>${esc(item.category)}</td><td>${esc(item.rarity)}</td><td>${money(price.amount, price.currency)}</td><td>${num(item.purchasesCount || 0)}</td></tr>`; }).join('') || '<tr><td colspan="5">Каталог пуст</td></tr>'}</tbody></table></div>`;
  const payments = rows => { const completed = rows.filter(item => item.status === 'completed'), issued = completed.reduce((sum, item) => sum + Number(item.gemsAmount || 0), 0), total = completed.reduce((sum, item) => sum + Number(item.amount || 0), 0); return `<div class="admin-section-intro"><div><span class="eyebrow">PAYMENTS</span><h3>Telegram Payments</h3><p>Платежи и выдача TeleGems читаются из server ledger. Компенсации проходят отдельным OWNER-действием.</p></div><span class="admin-scope">SERVER DATA</span></div><div class="admin-metric-grid">${metric('PAYMENTS', rows.length)}${metric('COMPLETED', completed.length, 'mint')}${metric('AMOUNT', total)}${metric('GEMS ISSUED', issued, 'violet')}</div><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Payment</th><th>Player</th><th>Package</th><th>Amount</th><th>Gems</th><th>Status</th><th>Date</th><th>Compensation</th></tr></thead><tbody>${rows.slice(0, 100).map(item => `<tr><td><small>${esc(item.id)}</small></td><td>${esc(item.playerId)}</td><td>${esc(item.packageId)}</td><td>${num(item.amount)} ${esc(item.currency)}</td><td>${num(item.gemsAmount)} 💎</td><td>${esc(item.status)}</td><td>${date(item.createdAt)}</td><td><form data-admin-payment-compensation><input type="hidden" name="paymentId" value="${esc(item.id)}"><input type="hidden" name="targetPlayerId" value="${esc(item.playerId)}"><input name="amount" type="number" min="1" step="1" placeholder="Gems"><input name="reason" required placeholder="Причина"><button type="submit">Выдать</button></form></td></tr>`).join('') || '<tr><td colspan="8">Нет платежей</td></tr>'}</tbody></table></div>`; };
  const games = items => `<div class="admin-section-intro"><div><span class="eyebrow">GAME ANALYTICS</span><h3>Games</h3><p>Launches, sessions, score and reward flow по зарегистрированным играм.</p></div></div><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Игра</th><th>Launches</th><th>Completed</th><th>Avg score</th><th>Play time</th><th>Rewards</th></tr></thead><tbody>${items.map(item => `<tr><td><b>${esc(item.title)}</b><small>${esc(item.id)}</small></td><td>${num(item.launches)}</td><td>${num(item.completed)}</td><td>${num(item.averageScore)}</td><td>${num(item.averagePlayTime)} sec</td><td>${num(item.rewardsGiven)}</td></tr>`).join('')}</tbody></table></div>`;
  const logs = (events, actions) => `<div class="admin-section-intro"><div><span class="eyebrow">AUDIT TRAIL</span><h3>Logs</h3><p>Analytics Events и действия OWNER хранятся в ограниченном журнале.</p></div></div><div class="admin-log-grid"><section><h4>Admin Action Log</h4><div class="admin-log-list">${actions.slice(0, 50).map(item => `<div class="admin-log-row"><b>${esc(item.action)}</b><span>${esc(item.currencyType || item.itemId || item.achievementId || '')}</span><small>${esc(item.reason || '—')} · ${date(item.timestamp)}</small></div>`).join('') || '<div class="admin-empty">Нет действий</div>'}</div></section><section><h4>Analytics Events</h4><div class="admin-log-list">${events.slice(0, 50).map(item => `<div class="admin-log-row"><b>${esc(item.event)}</b><span>${esc(item.gameId || 'platform')}</span><small>${date(item.createdAt)}</small></div>`).join('') || '<div class="admin-empty">Нет событий</div>'}</div></section></div>`;
  const security = data => {
    const proofs = data?.proofs || [], results = data?.results || [], fraud = data?.fraudEvents || [];
    return `<div class="admin-section-intro"><div><span class="eyebrow">SECURITY / REWARDS</span><h3>Server Reward Proofs</h3><p>Награды выдаются только после проверки результата сервером. Здесь видны выданные proofs, отклонённые результаты и anti-cheat события.</p></div><span class="admin-scope">SERVER DATA</span></div><div class="admin-metric-grid">${metric('ISSUED PROOFS', proofs.filter(item => item.status === 'issued').length, 'mint')}${metric('REJECTED RESULTS', results.filter(item => !item.validated).length, 'violet')}${metric('FRAUD EVENTS', fraud.length, 'cyan')}</div><div class="admin-table-wrap"><h4>Issued rewards</h4><table class="admin-table"><thead><tr><th>Proof</th><th>Player</th><th>Game</th><th>Reward</th><th>Status</th><th>Date</th></tr></thead><tbody>${proofs.slice(0, 50).map(item => { const reward = item.rewardData || item.reward || {}; return `<tr><td><small>${esc(item.id)}</small></td><td>${esc(item.playerId)}</td><td>${esc(item.gameId)}</td><td>${num(reward.coins || 0)} 🪙 · ${num(reward.xp || 0)} XP</td><td>${esc(item.status)}</td><td>${date(item.createdAt)}</td></tr>`; }).join('') || '<tr><td colspan="6">Нет reward proofs</td></tr>'}</tbody></table></div><div class="admin-table-wrap"><h4>Rejected results</h4><table class="admin-table"><thead><tr><th>Player</th><th>Game</th><th>Score</th><th>Reason</th><th>Date</th></tr></thead><tbody>${results.filter(item => !item.validated).slice(0, 50).map(item => `<tr><td>${esc(item.playerId)}</td><td>${esc(item.gameId)}</td><td>${num(item.score)}</td><td>${esc(item.rejectionCode || 'rejected')}</td><td>${date(item.createdAt)}</td></tr>`).join('') || '<tr><td colspan="5">Нет отклонённых результатов</td></tr>'}</tbody></table></div><div class="admin-table-wrap"><h4>Fraud events</h4><table class="admin-table"><thead><tr><th>Player</th><th>Game</th><th>Type</th><th>Date</th></tr></thead><tbody>${fraud.slice(0, 50).map(item => `<tr><td>${esc(item.playerId)}</td><td>${esc(item.gameId || '—')}</td><td>${esc(item.type)}</td><td>${date(item.createdAt)}</td></tr>`).join('') || '<tr><td colspan="4">Нет подозрительных событий</td></tr>'}</tbody></table></div>`;
  };
  const AdminView = { esc, num, date, renderShell: (session, active) => `<div class="admin-page"><header class="admin-header"><button class="icon-button" id="adminClose" type="button" aria-label="На главную">‹</button><div><small>TELEPLAY · RESTRICTED</small><h2>Admin Panel</h2></div><span class="admin-owner-badge">${esc(session.roleLabel || 'OWNER')}</span></header><div class="admin-owner-strip"><span>⚙️</span><div><b>${esc(session.username ? `@${session.username}` : session.telegramId)}</b><small>Owner access · Telegram ID ${esc(session.telegramId || 'не передан')}</small></div><i>SECURE</i></div><nav class="admin-tabs" aria-label="Разделы Admin Panel">${tabs(active)}</nav><main id="adminContent"></main></div>`, dashboard, players, economy, shop, payments, games, security, logs };
  window.TelePlayAdmin = window.TelePlayAdmin || {};
  window.TelePlayAdmin.View = AdminView;
})();
